import type { EntityInput, TechnologyInput } from "@/lib/schema";
import type { EvidenceGrade } from "@/lib/complementary";

/**
 * Recovery and rejuvenation, facet K: how recovery is measured, and who actually gets any of it.
 *
 * The rest of this front describes what cancer treatment takes and what comes back. Two questions sit under all
 * of it and were missing entirely.
 *
 *  - `rejuv-measure-*`: the instruments. Almost every number on the recovery literature comes from a
 *    questionnaire a patient filled in, and a reader will meet the same questionnaires in their own notes. Each
 *    record says what the instrument asks, what a score means, what counts as a difference that matters where
 *    somebody has published one, and what it misses. The objective tests belong here too: the walk test, the
 *    grip dynamometer, the exercise test, the scan that measures muscle, and the biological-age kit sold direct
 *    to the public, which is graded here rather than on the frontier page because the question behind it,
 *    should I buy one, is a measurement question.
 *  - `rejuv-access-*`: what a person is actually offered when treatment ends, country by country; the published
 *    inequities in who is referred to rehabilitation, psychological care, fertility preservation and exercise;
 *    and what the things on this front cost when they are not free.
 *
 * Grades travel as a tag `evidence:<grade>` and follow src/lib/complementary.ts: strong = consistent randomised
 * trials plus a major guideline recommendation; moderate = trials exist but small, mixed or single-setting;
 * insufficient = no reliable human evidence of benefit; no-benefit = adequately sized trials found nothing;
 * harm = toxicity, interaction, or use in place of standard treatment. A measurement is not an approach, so the
 * instrument and objective-test records carry no grade: there is nothing on them to recommend or warn against.
 * The records that describe something done to a person, electronic symptom monitoring and the consumer ageing
 * kit, carry one.
 *
 * Every identifier here was resolved against Crossref and the figures read from the abstract or full text of the
 * paper beside them. Three DOIs recalled from memory by another agent in this round were wrong, so nothing here
 * was written from memory. Where a source could not be reached the record says so instead of guessing.
 *
 * Records the corpus already holds are referenced rather than rewritten: `survivorship-care-plan`,
 * `epro-symptom-monitoring`, `exercise-oncology`, `structured-exercise-survivorship`, `prehabilitation`,
 * `psycho-oncology`, `fertility-preservation`, `financial-navigation`, `ct-body-composition-sarcopenia`,
 * `lymphoedema-decongestive-therapy` and `geriatric-assessment`. The mind facet owns
 * `rejuv-mind-access-to-psychological-care` and `rejuv-mind-fear-of-recurrence`; both are linked, not duplicated.
 *
 * British spelling.
 */

const asOf = "2026-10-02";
const W = (s: string) => `https://en.wikipedia.org/wiki/${s}`;
const doi = (label: string, d: string) => ({ label, url: `https://doi.org/${d}` });

const REJ = "rejuvenation";
const SUP = "supportive-care";
const SEC = [REJ, SUP];

const tech = (x: Omit<TechnologyInput, "kind" | "asOf">): TechnologyInput => ({ kind: "technology", asOf, ...x });
/** Tag set for a record that describes something done to a person, so it carries an honest grade. */
const T = (grade: EvidenceGrade, extra: string[] = []) => [REJ, "survivorship", `evidence:${grade}`, ...extra];
/** Tag set for a measurement or a description of a service. Nothing here is a recommendation, so no grade. */
const M = (extra: string[] = []) => [REJ, "survivorship", "measurement", ...extra];

